    welcomeDescription: "आचार्यशङ्करसांस्कृतिकैकतान्यासेन एकं पवित्रम् आंकिकं द्वारम्, अद्वैतवेदान्तस्य संरक्षणे, आंकिकीकरणे, वैश्विकप्रसारणे च समर्पितम्। आदिशङ्कराचार्यस्य परम्परया प्रेरितम्, जीवब्रह्मैक्यस्य गहनसत्यस्य अन्वेषणम् — जीवात्मनः परमात्मनश्च आवश्यिकैकत्वम्।",
    treasuryOfWisdom: "प्रज्ञायाः कोशः",
    treasuryIntro: "न्यासेन ग्रन्थानां विपुलः सङ्ग्रहः यत्नेन सम्पादितः, मूलभूतात् \"त्रिशास्त्रात्\" (प्रस्थानत्रयात्) उत्तरकालीनानां अद्वैताचार्याणां परिष्कृतवादग्रन्थपर्यन्तम्। अस्माकम् अभिलेखागारे विद्यन्ते:",
