    prakaranaGranthasLabel: "प्रकरणग्रन्थाः:",
    prakaranaGranthasDesc: "विवेकचूडामणिः, उपदेशसाहस्री, आत्मबोधः इत्यादयः आवश्यकाः प्रारम्भिकाः ग्रन्थाः।",
    scholasticTraditionLabel: "शास्त्रीयपरम्परा:",
    scholasticTraditionDesc: "भामतीविवरणसम्प्रदाययोः गहनम् अध्ययनम्, पद्मपादवाचस्पतिमिश्रविद्यारण्यस्वामिप्रभृतीनाम् आचार्याणां रचनाः।",
    regionalLuminariesLabel: "प्रादेशिकाः विद्वांसः:",
