    ourVisionSanskritikEkta: "अस्माकं दृष्टिः: सांस्कृतिकैकता",
    visionDescription: "आचार्यशङ्करसांस्कृतिकैकतान्यासस्य लक्ष्यानुसारम्, इदं ग्रन्थालयं केवलं पुस्तकानां भण्डारः नास्ति; सार्वभौमसामरस्यस्य साधनम् अस्ति। अद्वैतदर्शनं सर्वेभ्यः सुलभं कृत्वा, वयं \"अन्यत्वस्य\" सीमाः विलापयितुं सम्पूर्णास्तित्वस्य अन्तर्निहितैकत्वं प्रकाशयितुं च इच्छामः।",
    brahmanQuote: "\"ब्रह्म सत्यं जगन्मिथ्या जीवो ब्रह्मैव नापरः।\"",
