    authenticTranscriptionsLabel: "प्रामाणिकाः प्रतिलिपयः:",
    authenticTranscriptionsDesc: "आधुनिकपाठकेभ्यः सम्यक्स्वरूपणेन सटीकतया आंकिकीकृताः संस्कृतग्रन्थाः।",
    manuscriptPreservationLabel: "पाण्डुलिपिसंरक्षणम्:",
    manuscriptPreservationDesc: "अस्माकं विरासतस्य दीर्घायुषं सुनिश्चितं कर्तुं दुर्लभसंस्करणानां उच्चविभेदनस्कैनाः।",
