    welcomeDescription: "ಆಚಾರ್ಯ ಶಂಕರ ಸಾಂಸ್ಕೃತಿಕ ಏಕತಾ ನ್ಯಾಸದ ಒಂದು ಪವಿತ್ರ ಡಿಜಿಟಲ್ ಪೋರ್ಟಲ್, ಅದ್ವೈತ ವೇದಾಂತದ ಸಂರಕ್ಷಣೆ, ಡಿಜಿಟಲೀಕರಣ ಮತ್ತು ವಿಶ್ವವ್ಯಾಪಿ ಪ್ರಸಾರಕ್ಕೆ ಸಮರ್ಪಿತ. ಆದಿ ಶಂಕರಾಚಾರ್ಯರ ಪರಂಪರೆಯಿಂದ ಪ್ರೇರಿತ, ಜೀವ-ಬ್ರಹ್ಮ-ಐಕ್ಯದ ಗಹನ ಸತ್ಯವನ್ನು ಅನ್ವೇಷಿಸುತ್ತದೆ: ವ್ಯಕ್ತಿ ಆತ್ಮ ಮತ್ತು ಪರಮ ಸತ್ಯದ ಅನಿವಾರ್ಯ ಏಕತೆ.",
    treasuryOfWisdom: "ಜ್ಞಾನದ ಭಂಡಾರ",
    treasuryIntro: "ನ್ಯಾಸವು ಮೂಲಭೂತ \"ತ್ರಿಶಾಸ್ತ್ರ\" (ಪ್ರಸ್ಥಾನತ್ರಯ) ದಿಂದ ನಂತರದ ಅದ್ವೈತ ಆಚಾರ್ಯರ ಪರಿಷ್ಕೃತ ತಾರ್ಕಿಕ ಕೃತಿಗಳವರೆಗೆ ಗ್ರಂಥಗಳ ವಿಶಾಲ ಸಂಗ್ರಹವನ್ನು ಎಚ್ಚರಿಕೆಯಿಂದ ಸಂಕಲಿಸಿದೆ. ನಮ್ಮ ದಾಖಲೆಗಳಲ್ಲಿ ಸೇರಿವೆ:",
