    scholasticTraditionLabel: "ಶಾಸ್ತ್ರೀಯ ಪರಂಪರೆ:",
    scholasticTraditionDesc: "ಭಾಮತಿ ಮತ್ತು ವಿವರಣ ಶಾಲೆಗಳ ಆಳವಾದ ಅಧ್ಯಯನ, ಪದ್ಮಪಾದ, ವಾಚಸ್ಪತಿ ಮಿಶ್ರ ಮತ್ತು ವಿದ್ಯಾರಣ್ಯ ಸ್ವಾಮಿ ಮುಂತಾದ ಆಚಾರ್ಯರ ಕೃತಿಗಳು.",
    regionalLuminariesLabel: "ಪ್ರಾದೇಶಿಕ ವಿದ್ವಾಂಸರು:",
