    scholarlySearchLabel: "ವಿದ್ವತ್ ಹುಡುಕಾಟ:",
    scholarlySearchDesc: "ಲೇಖಕ, ಕಾಲ ಅಥವಾ ನಿರ್ದಿಷ್ಟ ತಾತ್ತ್ವಿಕ ಉಪ-ವಿಷಯದ ಮೂಲಕ ಮಾರ್ಗದರ್ಶನ.",
    saVidyaQuote: "\"ಸಾ ವಿದ್ಯಾ ಯಾ ವಿಮುಕ್ತಯೇ\" — ಜ್ಞಾನವೇ ಮೋಕ್ಷ ನೀಡುವುದು.",
    invitationText: "ಜ್ಞಾನದ ಈ ಸಾಗರದಲ್ಲಿ ಅನ್ವೇಷಿಸಲು ನಾವು ನಿಮ್ಮನ್ನು ಆಹ್ವಾನಿಸುತ್ತೇವೆ. ಆಚಾರ್ಯ ಶಂಕರರ ಕೃಪೆಯು ನಿಮ್ಮ ಅನ್ವೇಷಣೆಯನ್ನು ಕ್ಷಣಿಕದಿಂದ ಶಾಶ್ವತಕ್ಕೆ ಮಾರ್ಗದರ್ಶನ ಮಾಡಲಿ.",
