    welcomeDescription: "ఆచార్య శంకర సాంస్కృతిక ఏకతా న్యాస్ యొక్క ఒక పవిత్ర డిజిటల్ పోర్టల్, అద్వైత వేదాంతం యొక్క సంరక్షణ, డిజిటలీకరణ మరియు ప్రపంచవ్యాప్త ప్రచారానికి అంకితం. ఆది శంకరాచార్యుల వారసత్వం నుండి ప్రేరణ పొంది, జీవ-బ్రహ్మ-ఐక్యం యొక్క గాఢ సత్యాన్ని అన్వేషిస్తుంది: వ్యక్తి ఆత్మ మరియు పరమ సత్యం యొక్క అనివార్య ఏకత్వం.",
    treasuryOfWisdom: "జ్ఞాన భాండాగారం",
    treasuryIntro: "న్యాస్ మూలభూతమైన \"త్రికానన్\" (ప్రస్థానత్రయి) నుండి తరువాతి అద్వైత ఆచార్యుల పరిష్కృత తార్కిక రచనల వరకు విస్తరించిన గ్రంథాల విశాల సంకలనాన్ని శ్రద్ధగా సంకలించింది. మా ఆర్కైవ్‌లలో ఉన్నవి:",
