    saVidyaQuote: "\"సా విద్యా యా విముక్తయే\" — జ్ఞానమే మోక్షమిచ్చునది.",
    invitationText: "జ్ఞానం యొక్క ఈ సాగరంలో అన్వేషించడానికి మేము మిమ్మల్ని ఆహ్వానిస్తున్నాము. ఆచార్య శంకరుల కృపతో మీ అన్వేషణ క్షణికం నుండి శాశ్వతం వైపు మార్గనిర్దేశం పొందుగాక.",
