    welcomeDescription: "Un portail numérique sacré de l'Acharya Shankar Sanskritik Ekta Nyas, dédié à la préservation, à la numérisation et à la diffusion mondiale de l'Advaita Vedanta. Inspiré par l'héritage d'Adi Shankaracharya, explorant la vérité profonde de Jiva-Brahma-Aikya : l'unité essentielle de l'âme individuelle et de la Réalité Suprême.",
    treasuryOfWisdom: "Le Trésor de la Sagesse",
    treasuryIntro: "Le Nyas a méticuleusement constitué une vaste collection de textes, allant du \"Triple Canon\" fondamental (Prasthanatrayi) aux œuvres dialectiques sophistiquées des maîtres ultérieurs de l'Advaita. Nos archives comprennent :",
    prasthanatriyaBhashyasLabel: "Prasthanatrayi Bhashyas :",
    prasthanatriyaBhashyasDesc: "Les commentaires fondamentaux sur les Upanishads, la Bhagavad Gita et les Brahma Sutras.",
    prakaranaGranthasLabel: "Prakarana Granthas :",
    prakaranaGranthasDesc: "Monographies introductives essentielles telles que Vivekachudamani, Upadesha Sahasri et Atma Bodha.",
    scholasticTraditionLabel: "La Tradition Scolastique :",
    scholasticTraditionDesc: "Études approfondies des écoles Bhamati et Vivarana, incluant les œuvres de maîtres comme Padmapada, Vachaspati Misra et Vidyaranya Swami.",
    regionalLuminariesLabel: "Luminaires régionaux :",
    regionalLuminariesDesc: "Œuvres rares et significatives de toute l'Inde, telles que les chefs-d'œuvre de Sri Bellamkonda Rama Raya et Shrimad Bodhendra Saraswati.",
    ourVisionSanskritikEkta: "Notre Vision : Sanskritik Ekta",
    visionDescription: "En accord avec la mission de l'Acharya Shankar Sanskritik Ekta Nyas, cette bibliothèque est plus qu'un dépôt de livres ; c'est un outil d'harmonie universelle. En rendant la philosophie Advaita accessible à tous, nous visons à dissoudre les frontières de l'« altérité » et à révéler l'unité sous-jacente de toute existence.",
    brahmanQuote: "\"Brahman est la seule Vérité, le Monde est une apparence, et le Soi individuel n'est autre que Brahman.\"",
