    visionDescription: "秉承 Acharya Shankar Sanskritik Ekta Nyas 的使命，本图书馆不仅是书籍的宝库，更是促进普世和谐的工具。通过使 Advaita 哲学对所有人开放，我们旨在消解「他者」的界限，揭示一切存在的内在统一。",
    brahmanQuote: "\"Brahman 是唯一的真理，世界是幻相，个体自我与 Brahman 无异。\"",
