    welcomeDescription: "Acharya Shankar Sanskritik Ekta Nyasによる神聖なデジタルポータルで、Advaita Vedantaの保存、デジタル化、世界的な普及に捧げられています。Adi Shankaracharyaの遺産に触発され、個々の魂と最高の現実の本質的な一体性であるJiva-Brahma-Aikyaの深遠な真実を探求します。",
    treasuryOfWisdom: "知恵の宝庫",
    treasuryIntro: "Nyasは、基礎的な「三重規範」（Prasthanatrayi）から後期Advaitaの達人による高度な弁証法的作品まで、広範なテキストコレクションを丹念に編纂しました。私たちのアーカイブには以下が含まれます：",
