    ourVisionSanskritikEkta: "私たちのビジョン：Sanskritik Ekta",
    visionDescription: "Acharya Shankar Sanskritik Ekta Nyasの使命に沿って、このライブラリは単なる書籍の保管庫ではなく、普遍的な調和のためのツールです。Advaita哲学をすべての人にアクセス可能にすることで、「他者性」の境界を溶かし、すべての存在の根底にある統一性を明らかにすることを目指しています。",
