    welcomeDescription: "ආචාර්ය ශංකර සංස්කෘතික එක්තා න්‍යාසය විසින් පවත්වාගෙන යන, අද්වෛත වේදන්තය ආරක්ෂා කිරීම, ඩිජිටල් කිරීම, සහ ගෝලීය ව්‍යාප්තිය සඳහා කැපවූ පූජනීය ඩිජිටල් ද්වාරයකි. ආදි ශංකරචාර්යයන්ගේ උරුමයෙන් ප්‍රේරණය ලැබූ, ජීව-බ්‍රහ්ම-ඒකය: පුද්ගලික ආත්මය සහ සර්වෝත්කෘෂ්ට සත්‍යය අතරේ මූලික එකමත්වය සොයා බලන්න.",
