    visionDescription: "ආචාර්ය ශංකර සංස්කෘතික එක්තා න්‍යාසයේ මෙහෙයුමට අනුකූලව, මෙම පුස්තකාලය පොත් එකතුවක් පමණක් නොව, විශ්ව සාමය සඳහා උපකරණයකි. අද්වෛත දර්ශනය සැමට ප්‍රවේශය ලබා දීමෙන්, අපි \"අනෙකුත්කම\" යන සීමා විසුරුවා දමා සියලුම අස්ථිතින්ගේ මූලික එකමත්වය අනාවරණය කිරීමට අපේක්ෂා කරමු.",
    brahmanQuote: "\"බ්‍රහ්මන් පමණක් සත්‍යයයි, ලෝකය පෙනෙන ආකාරයකි, සහ පුද්ගලික ආත්මය බ්‍රහ්මන්ට වෙනත් කිසිවක් නොවේ.\"",
