    welcomeDescription: "Deriyek pîroz a dijîtal ji hêla Acharya Shankar Sanskritik Ekta Nyas ve, ku bo parastin, dijîtalîzasyon û belavkirina cîhanî ya Advaita Vedanta xweşkirî ye. Ji bo xatirê Adi Shankaracharya, ku rastiyê girîng a Jiva-Brahma-Aikya: yekbûna bingehîn a cana taybet û Rastiyê Bilind dîtibin.",
    treasuryOfWisdom: "Xezîneyê Zanyarî",
    treasuryIntro: "Nyas koleksiyonek mezin a nivîsan bi baldarî ve hatî çêkirin, ji \"Triple Canon\" (Prasthanatrayi) ya bingehîn heta karên dialektîkî yên pêşîn a xwendekarên Advaita. Arşîvên me di nav de:",
