    visionDescription: "Di hevpeyvîna bi armanca Acharya Shankar Sanskritik Ekta Nyas de, vê pirtûkxaneyê ne tenê arşîvê pirtûkan e; lê belê amûrek ji bo hevahengiya cîhanî ye. Bi kirina felsefeya Advaita bi hemû kesan re, em armancê me ku sînorên \"dîtiya din\" bişînin û yekbûna bingehîn a hemû hebûna nîşan bidin.",
