    welcomeDescription: "Acharya Shankar Sanskritik Ekta Nyas-ийн ариун дижитал портал, Advaita Vedanta-г хадгалах, дижиталжуулах, дэлхий даяар түгээхэд зориулагдсан. Adi Shankaracharya-ийн өв уламжлалаас урам зориг авсан, Jiva-Brahma-Aikya-ийн гүн гүнзгий үнэнийг судлах: хувь хүний сүнс ба Дээд Бодит байдлын үндсэн нэгдэл.",
    treasuryOfWisdom: "Мэргэн ухааны сан",
    treasuryIntro: "Nyas нь үндсэн \"Гурвалсан Канон\" (Prasthanatrayi)-оос эхлээд хожуу үеийн Advaita мастеруудын нарийн диалектик бүтээлүүд хүртэлх өргөн хүрээний текстүүдийг нарийн цуглуулсан. Манай архивт дараах зүйлс багтсан:",
