    regionalLuminariesLabel: "Бүс нутгийн гэрэлтүүлэгчид:",
    regionalLuminariesDesc: "Энэтхэг даяархи ховор, чухал бүтээлүүд, жишээлбэл, Sri Bellamkonda Rama Raya болон Shrimad Bodhendra Saraswati-ийн бүтээлүүд.",
    ourVisionSanskritikEkta: "Бидний алсын хараа: Sanskritik Ekta",
    visionDescription: "Acharya Shankar Sanskritik Ekta Nyas-ийн эрхэм зорилготой нийцүүлэн, энэ номын сан нь номын сангаас илүү их зүйл юм; энэ нь бүх нийтийн эв нэгдлийн хэрэгсэл юм. Advaita философийг хүн бүрт хүртээмжтэй болгох замаар бид \"өөр байдал\"-ын хил хязгаарыг арилгаж, бүх оршихуйн үндсэн нэгдлийг илчлэхийг зорьж байна.",
    brahmanQuote: "\"Брахман бол цорын ганц үнэн, ертөнц бол үзэгдэл, хувь хүн өөрөө Брахман юм.\"",
