    welcomeDescription: "Acharya Shankar Sanskritik Ekta Nyas မှ စီစဉ်ထားသော သန့်ရှင်းသော ဒစ်ဂျစ်တယ် ဗဟို၊ Advaita Vedanta ၏ ထိန်းသိမ်းမှု၊ ဒစ်ဂျစ်တယ်ပြုလုပ်ခြင်းနှင့် ကမ္ဘာလုံးဆိုင်ရာ ဖြန့်ဝေမှုအတွက် အပ်နှံထားသည်။ Adi Shankaracharya ၏ အမွေအနှစ်မှ လှုံ့ဆော်မှုရရှိပြီး၊ Jiva-Brahma-Aikya ၏ နက်နဲသော အမှန်တရားကို ရှာဖွေခြင်း၊ တစ်ကိုယ်ရည်နှင့် အမြင့်ဆုံး အဖြစ်၏ အဓိက တစ်ခုဖြစ်ခြင်းကို ရှာဖွေခြင်း။",
    treasuryOfWisdom: "ပညာ၏ ငွေတိုက်",
    treasuryIntro: "Nyas သည် အခြေခံ \"Triple Canon\" (Prasthanatrayi) မှ စ၍ နောက်ပိုင်း Advaita မဟာဗျူဟာများ၏ ရှုထောင့်များအထိ စာအုပ်များ၏ အကြီးအကျယ် စုဆောင်းမှုကို ကြိုးစားစွာ စုဆောင်းထားသည်။ ကျွန်ုပ်တို့၏ မူရင်းစာရင်းများတွင် ပါဝင်သည်-",
