    scholasticTraditionLabel: "ပညာရေး အထုံးအနာ",
    scholasticTraditionDesc: "Bhamati နှင့် Vivarana ကျောင်းများကို နက်နဲစွာ လေ့လာခြင်း၊ Padmapada, Vachaspati Misra, နှင့် Vidyaranya Swami ကဲ့သို့သော မဟာဗျူဟာများ၏ လက်ရာများအပါအဝင်။",
    regionalLuminariesLabel: "ဒေသဆိုင်ရာ အလင်းရောင်များ",
    regionalLuminariesDesc: "India အနှံ့မှ ရှားပါးပြီး အရေးကြီးသော လက်ရာများ၊ Sri Bellamkonda Rama Raya နှင့် Shrimad Bodhendra Saraswati ၏ မဟာဗျူဟာများကဲ့သို့သော လက်ရာများ။",
    ourVisionSanskritikEkta: "ကျွန်ုပ်တို့၏ ရည်မှန်းချက်: Sanskritik Ekta",
    visionDescription: "Acharya Shankar Sanskritik Ekta Nyas ၏ မစ်ရှင်နှင့် ကိုက်ညီစွာ၊ ဤ စာကြည့်တိုက်သည် စာအုပ်များ၏ သိုလှောင်ရုံထက် ပို၍ ဖြစ်သည်။ ၎င်းသည် ကမ္ဘာလုံးဆိုင်ရာ ညီညွတ်မှုအတွက် ကိရိယာတစ်ခုဖြစ်သည်။ Advaita အတွေးအခေါ်ကို အားလုံးအတွက် ရရှိနိုင်စေရန်ဖြင့်၊ \"အခြားသူ\" ၏ နယ်နိမိတ်များကို ဖျက်သိမ်းပြီး အလုံးစုံ ဖြစ်တည်မှု၏ အခြေခံ ညီညွတ်မှုကို ဖော်ထုတ်ရန် ကျွန်ုပ်တို့ ရည်ရွယ်ပါသည်။",
    brahmanQuote: "\"Brahman သည် တစ်ခုတည်းသော အမှန်တရားဖြစ်သည်၊ ကမ္ဘာသည် ပုံပျက်ခြင်းဖြစ်ပြီး၊ တစ်ကိုယ်ရည်သည် Brahman သာဖြစ်သည်။\"",
    featuresOfDigitalLibrary: "ဒစ်ဂျစ်တယ် စာကြည့်တိုက်၏ အင်္ဂါရပ်များ",
