    visionDescription: "આચાર્ય શંકર સંસ્કૃતિક એકતા ન્યાસના મિશન સાથે સંકલિત, આ લાઇબ્રેરી માત્ર પુસ્તકોનો સંગ્રહ નથી; તે સર્વજ્ઞાતિક સુમેળ માટેનું સાધન છે. અદ્વૈત તત્ત્વજ્ઞાનને સૌ માટે ઉપલબ્ધ બનાવીને, અમે \"અન્યતા\"ની સીમાઓને વિલિન કરવા અને સર્વ અસ્તિત્વની મૂળભૂત એકતાને પ્રગટ કરવા માંગીએ છીએ.",
    brahmanQuote: "\"બ્રહ્મન જ એકમાત્ર સત્ય છે, જગત એક પ્રત્યભાસ છે, અને વ્યક્તિગત આત્મા બ્રહ્મન સિવાય બીજું નથી.\"",
    featuresOfDigitalLibrary: "ડિજિટલ લાઇબ્રેરીની વિશેષતાઓ",
