    welcomeDescription: "আচার্য শংকৰ সংস্কৃতিক একতা ন্যাসৰ দ্বাৰা এক পবিত্ৰ ডিজিটেল পোর্টেল, অদ্বৈত বেদান্তৰ সংৰক্ষণ, ডিজিটাইজেচন আৰু বিশ্বব্যাপী প্ৰচাৰৰ বাবে উত্সৰ্গিত। আদি শংকৰাচাৰ্যৰ ঐতিহ্যৰ পৰা অনুপ্ৰাণিত, জীৱ-ব্ৰহ্ম-ঐক্যৰ গভীৰ সত্যৰ সন্ধান: ব্যক্তিগত আত্মা আৰু পৰম সত্যৰ মৌলিক একত্ব।",
    treasuryOfWisdom: "জ্ঞানৰ ধনভাণ্ডাৰ",
    treasuryIntro: "ন্যাসে সাৱধানে এক বিশাল পাঠৰ সংগ্ৰহ সজাইছে, যি মুল \"ত্ৰিপল ক্যানন\" (প্ৰস্থানত্ৰয়ী)ৰ পৰা আৰম্ভ কৰি পিছৰ অদ্বৈত আচার্যসকলৰ জটিল দ্বন্দ্বমূলক কৰ্মলৈকে বিস্তৃত। আমাৰ সংৰক্ষণত অন্তৰ্ভুক্ত হৈছে:",
