    scholasticTraditionLabel: "শিক্ষামূলক পৰম্পৰা:",
    scholasticTraditionDesc: "ভামতী আৰু বিবৰণ বিদ্যালয়ৰ গভীৰ অধ্যয়ন, পদ্মপাদ, বাচস্পতি মিশ্ৰ, আৰু বিদ্যারণ্য স্বামীৰ দৰে আচার্যসকলৰ কৰ্মসহ।",
    regionalLuminariesLabel: "আঞ্চলিক প্ৰভা:",
    regionalLuminariesDesc: "ভাৰতৰ বিভিন্ন স্থানৰ দুৰ্লভ আৰু গুৰুত্বপূৰ্ণ কৰ্ম, যেনে শ্ৰী বেল্লামকোণ্ড ৰাম ৰায়া আৰু শ্ৰীমদ্ বোধেন্দ্ৰ স্বামীৰ মহাকাব্য।",
    ourVisionSanskritikEkta: "আমাৰ দৃষ্টি: সংস্কৃতিক একতা",
    visionDescription: "আচার্য শংকৰ সংস্কৃতিক একতা ন্যাসৰ মিছনৰ সৈতে সঙ্গতি ৰাখি, এই গ্ৰন্থাগাৰ কেৱল গ্ৰন্থৰ সংগ্ৰহ নহয়; ই বিশ্বজনীন সম্প্ৰীতিৰ এক সঁজুলি। অদ্বৈত দৰ্শন সকলোলৈ উপলব্ধ কৰি, আমি \"অন্যতা\"ৰ সীমা বিলীন কৰি সকলো অস্তিত্বৰ অন্তৰ্নিহিত একত্ব প্ৰকাশ কৰিবলৈ লক্ষ্য কৰিছো।",
    brahmanQuote: "\"ব্ৰহ্মই একমাত্ৰ সত্য, পৃথিৱী এটা প্ৰতিভাস, আৰু ব্যক্তিগত আত্মা ব্ৰহ্মৰ পৰা পৃথক নহয়।\"",
