    saVidyaQuote: "\"সেই বিদ্যাই মুক্তি দিয়ে।\" — সা বিদ্যা যা বিমুক্তয়ে",
    invitationText: "এই জ্ঞানৰ মহাসাগৰ অন্বেষণ কৰিবলৈ আমি আপোনাক আমন্ত্ৰণ জনাইছো। আচার্য শংকৰৰ কৃপাই আপোনাৰ অনুসন্ধানক ক্ষণস্থায়ী পৰা শাশ্বতলৈ পথ দেখুৱাওক।",
