    ourVisionSanskritikEkta: "आमचें दृष्टिकोन: संस्कृतिक एकता",
    visionDescription: "आचार्य शंकर संस्कृतिक एकता न्यासाच्या मिशनशी सुसंगत, ही लायब्ररी फक्त पुस्तकांचें भांडार नाही; ती सार्वत्रिक एकतेसाठी एक साधन आहे. अद्वैत तत्त्वज्ञान सर्वांसाठी उपलब्ध करून देऊन, आम्ही 'इतरत्व' च्या सीमांना विरघळवून सर्व अस्तित्वाचें अंतर्निहित एकत्व उघड करण्याचें उद्दिष्ट ठेवतो.",
    brahmanQuote: "\"ब्रह्म सत्य आहे, जग एक भास आहे, आनी वैयक्तिक आत्मा ब्रह्मच आहे.\"",
