    eternalEchoOfNonDuality: "അദ്വിതീയതയുടെ ശാശ്വത പ്രതിധ്വനി",
    welcomeDescription: "ആചാര്യ ശങ്കർ സാംസ്കാരിക ഏകതാ ന്യാസിന്റെ ഒരു വിശുദ്ധ ഡിജിറ്റൽ പോർട്ടൽ, അദ്വൈത വേദാന്തത്തിന്റെ സംരക്ഷണം, ഡിജിറ്റലൈസേഷൻ, ആഗോള പ്രചരണം എന്നിവയ്ക്ക് സമർപ്പിച്ചിരിക്കുന്നു. ആദി ശങ്കരാചാര്യരുടെ പാരമ്പര്യത്തിൽ പ്രചോദനം പ്രാപിച്ച്, ജീവ-ബ്രഹ്മ-ഐക്യത്തിന്റെ ആഴത്തിലുള്ള സത്യത്തെ അന്വേഷിക്കുന്നു: വ്യക്തിഗത ആത്മാവിന്റെയും പരമസത്യത്തിന്റെയും അടിസ്ഥാന ഏകത്വം.",
    treasuryOfWisdom: "ജ്ഞാനത്തിന്റെ നിധി",
    treasuryIntro: "ന്യാസം അടിസ്ഥാന \"ത്രിപിടകം\" (പ്രസ്ഥാനത്രയി) മുതൽ പിന്നീട് അദ്വൈത ആചാര്യന്മാരുടെ സങ്കീർണ്ണമായ തർക്ക കൃതികൾ വരെ വ്യാപിക്കുന്ന ഒരു വിശാലമായ വാചക ശേഖരം സൂക്ഷ്മമായി സമാഹരിച്ചിട്ടുണ്ട്. ഞങ്ങളുടെ ആർക്കൈവുകളിൽ ഉൾപ്പെടുന്നു:",
    prasthanatriyaBhashyasLabel: "പ്രസ്ഥാനത്രയി ഭാഷ്യങ്ങൾ:",
    prasthanatriyaBhashyasDesc: "ഉപനിഷത്തുകൾ, ഭഗവദ് ഗീത, ബ്രഹ്മ സൂത്രങ്ങൾ എന്നിവയുടെ അടിസ്ഥാന വ്യാഖ്യാനങ്ങൾ.",
    prakaranaGranthasLabel: "പ്രകരണ ഗ്രന്ഥങ്ങൾ:",
    prakaranaGranthasDesc: "വിവേകചൂഡാമണി, ഉപദേശ സഹസ്രി, ആത്മബോധം പോലുള്ള അടിസ്ഥാന പരിചയ ഗ്രന്ഥങ്ങൾ.",
    scholasticTraditionLabel: "പണ്ഡിത പാരമ്പര്യം:",
    scholasticTraditionDesc: "ഭാമതി, വിവരണ പാഠശാലകളിലെ ആഴത്തിലുള്ള പഠനങ്ങൾ, പത്മപാദ, വാചസ്പതി മിശ്ര, വിദ്യാരണ്യ സ്വാമി എന്നിവരുടെ കൃതികൾ ഉൾപ്പെടെ.",
    regionalLuminariesLabel: "പ്രാദേശിക പ്രതിഭകൾ:",
    regionalLuminariesDesc: "ഇന്ത്യയുടെ വിവിധ ഭാഗങ്ങളിൽ നിന്നുള്ള അപൂർവവും പ്രധാനവുമായ കൃതികൾ, ശ്രീ ബെല്ലംകൊണ്ട രാമരായ, ശ്രീമദ് ബോധേന്ദ്ര സരസ്വതി എന്നിവരുടെ മഹാകൃതികൾ പോലുള്ളവ.",
    ourVisionSanskritikEkta: "ഞങ്ങളുടെ ദർശനം: സാംസ്കാരിക ഏകത",
    visionDescription: "ആചാര്യ ശങ്കർ സാംസ്കാരിക ഏകതാ ന്യാസിന്റെ ദൗത്യത്തിന് അനുസൃതമായി, ഈ ലൈബ്രറി പുസ്തകങ്ങളുടെ ഒരു ശേഖരത്തിലധികമാണ്; ഇത് സർവ്വത്ര ഐക്യത്തിനുള്ള ഒരു ഉപകരണം കൂടിയാണ്. അദ്വൈത തത്ത്വശാസ്ത്രം എല്ലാവർക്കും ലഭ്യമാക്കുന്നതിലൂടെ, \"മറ്റുള്ളവരുടെ\" അതിർത്തികൾ അപ്രത്യക്ഷമാക്കുകയും എല്ലാ സത്തകളുടെയും അടിസ്ഥാന ഐക്യത്തെ വെളിപ്പെടുത്തുകയും ചെയ്യുകയാണ് ഞങ്ങളുടെ ലക്ഷ്യം.",
    brahmanQuote: "\"ബ്രഹ്മം മാത്രമാണ് സത്യം, ലോകം പ്രത്യക്ഷമാണ്, വ്യക്തി ആത്മാവ് ബ്രഹ്മത്തിൽ നിന്ന് വ്യത്യസ്തമല്ല.\"",
    featuresOfDigitalLibrary: "ഡിജിറ്റൽ ലൈബ്രറിയുടെ സവിശേഷതകൾ",
    authenticTranscriptionsLabel: "പ്രാമാണികമായ പകർപ്പുകൾ:",
    authenticTranscriptionsDesc: "ആധുനിക വായനക്കാർക്കായി ശരിയായ ഫോർമാറ്റിംഗോടെ ഡിജിറ്റലൈസ് ചെയ്ത സംസ്കൃത വാചകങ്ങൾ.",
    manuscriptPreservationLabel: "പാണ്ഡുലിപി സംരക്ഷണം:",
    manuscriptPreservationDesc: "നമ്മുടെ പൈതൃകത്തിന്റെ ദീർഘായുസ്സിനായി അപൂർവ പതിപ്പുകളുടെ ഉയർന്ന റെസല്യൂഷൻ സ്കാനുകൾ.",
    scholarlySearchLabel: "പണ്ഡിതാന്വേഷണം:",
    scholarlySearchDesc: "രചയിതാവ്, കാലഘട്ടം, അല്ലെങ്കിൽ പ്രത്യേക തത്ത്വശാസ്ത്ര ഉപവിഷയം എന്നിവയിലൂടെ നാവിഗേറ്റ് ചെയ്യുക.",
    saVidyaQuote: "\"വിദ്യ മോചിപ്പിക്കുന്നതുതന്നെയാണ്.\" — സാ വിദ്യാ യാ വിമുക്തയേ",
    invitationText: "ഈ ജ്ഞാനസമുദ്രം അന്വേഷിക്കാൻ ഞങ്ങൾ നിങ്ങളെ ക്ഷണിക്കുന്നു. ആചാര്യ ശങ്കറിന്റെ കൃപ നിങ്ങളുടെ അന്വേഷണത്തെ താത്കാലികത്തിൽ നിന്ന് ശാശ്വതത്തിലേക്ക് നയിക്കട്ടെ.",
    managedByNyas: "ആചാര്യ ശങ്കർ സാംസ്കാരിക ഏകതാ ന്യാസം, മധ്യപ്രദേശ്, ഇത് നിയന്ത്രിക്കുന്നു.",
    backToHomeWelcome: "ഹോമിലേക്ക് മടങ്ങുക",
