    welcomeDescription: "ਆਚਾਰ੍ਯ ਸ਼ੰਕਰ ਸੰਸਕ੍ਰਿਤਿਕ ਏਕਤਾ ਨ੍ਯਾਸ ਦੁਆਰਾ ਇੱਕ ਪਵਿੱਤਰ ਡਿਜੀਟਲ ਪੋਰਟਲ, ਜੋ ਅਦਵੈਤ ਵੇਦਾਂਤ ਦੇ ਸੰਰਕਸ਼ਣ, ਡਿਜੀਟਲਾਈਜ਼ੇਸ਼ਨ ਅਤੇ ਵਿਸ਼ਵ ਪੱਧਰ 'ਤੇ ਪ੍ਰਸਾਰ ਲਈ ਸਮਰਪਿਤ ਹੈ। ਆਦਿ ਸ਼ੰਕਰਾਚਾਰ੍ਯ ਦੀ ਵਿਰਾਸਤ ਤੋਂ ਪ੍ਰੇਰਿਤ, ਜੀਵ-ਬ੍ਰਹਮਾ-ਐਕ੍ਯਾ ਦੇ ਗਹਿਰੇ ਸੱਚ ਦੀ ਖੋਜ ਕਰਦਾ ਹੈ: ਵਿਅਕਤੀਗਤ ਆਤਮਾ ਅਤੇ ਪਰਮ ਸਤ੍ਯ ਦੀ ਮੂਲ ਏਕਤਾ।",
