    ourVisionSanskritikEkta: "ਸਾਡਾ ਦਰਸ਼ਨ: ਸੰਸਕ੍ਰਿਤਿਕ ਏਕਤਾ",
    visionDescription: "ਆਚਾਰ੍ਯ ਸ਼ੰਕਰ ਸੰਸਕ੍ਰਿਤਿਕ ਏਕਤਾ ਨ੍ਯਾਸ ਦੇ ਮਿਸ਼ਨ ਦੇ ਅਨੁਸਾਰ, ਇਹ ਲਾਇਬ੍ਰੇਰੀ ਸਿਰਫ ਕਿਤਾਬਾਂ ਦਾ ਸੰਗ੍ਰਹਿ ਨਹੀਂ ਹੈ; ਇਹ ਵਿਸ਼ਵ ਭਾਈਚਾਰੇ ਲਈ ਇੱਕ ਸਾਧਨ ਹੈ। ਅਦਵੈਤ ਫ਼ਲਸਫ਼ੇ ਨੂੰ ਸਭ ਲਈ ਪਹੁੰਚਯੋਗ ਬਣਾਕੇ, ਅਸੀਂ \"ਹੋਰਪਨ\" ਦੀਆਂ ਹੱਦਾਂ ਨੂੰ ਖਤਮ ਕਰਨ ਅਤੇ ਸਾਰੇ ਅਸਤਿਤਵ ਦੀ ਮੂਲ ਏਕਤਾ ਨੂੰ ਪ੍ਰਗਟ ਕਰਨ ਦਾ ਲਕਸ਼ ਰੱਖਦੇ ਹਾਂ।",
    brahmanQuote: "\"ਬ੍ਰਹਮ ਹੀ ਸੱਚ ਹੈ, ਸੰਸਾਰ ਇੱਕ ਦ੍ਰਿਸ਼ਟੀਭਰਮ ਹੈ, ਅਤੇ ਵਿਅਕਤੀਗਤ ਆਤਮਾ ਬ੍ਰਹਮ ਤੋਂ ਵੱਖਰਾ ਨਹੀਂ ਹੈ।\"",
    featuresOfDigitalLibrary: "ਡਿਜੀਟਲ ਲਾਇਬ੍ਰੇਰੀ ਦੇ ਵਿਸ਼ੇਸ਼ਤਾਵਾਂ",
