    saVidyaQuote: "\"ਗਿਆਨ ਉਹ ਹੈ ਜੋ ਮੁਕਤੀ ਦਿੰਦਾ ਹੈ।\" — ਸਾ ਵਿਦ੍ਯਾ ਯਾ ਵਿਮੁਕ੍ਤਯੇ",
    invitationText: "ਅਸੀਂ ਤੁਹਾਨੂੰ ਇਸ ਗਿਆਨ ਦੇ ਸਮੁੰਦਰ ਦੀ ਖੋਜ ਕਰਨ ਲਈ ਸੱਦਾ ਦਿੰਦੇ ਹਾਂ। ਆਚਾਰ੍ਯ ਸ਼ੰਕਰ ਦੀ ਕਿਰਪਾ ਤੁਹਾਡੇ ਅਸਥਾਈ ਤੋਂ ਸਦੀਵੀ ਦੀ ਖੋਜ ਵਿੱਚ ਮਦਦਗਾਰ ਹੋਵੇ।",
