    welcomeDescription: "आचार्य शङ्कर सांस्कृतिक एकता न्यासद्वारा एक पवित्र डिजिटल पोर्टल, अद्वैत वेदान्तको संरक्षण, डिजिटलीकरण, र विश्वव्यापी प्रसारको लागि समर्पित। आदि शङ्कराचार्यको विरासतबाट प्रेरित, जीव-ब्रह्म-ऐक्यको गहन सत्यको अन्वेषण: व्यक्तिगत आत्मा र परम सत्यको मौलिक एकता।",
