    visionDescription: "आचार्य शङ्कर सांस्कृतिक एकता न्यासको मिशनसँग मेल खाने गरी, यो पुस्तकालय पुस्तकहरूको भण्डार मात्र होइन; यो सार्वभौमिक सद्भावको लागि एक उपकरण हो। अद्वैत दर्शनलाई सबैका लागि पहुँचयोग्य बनाउँदै, हामी \"अन्यताको\" सीमाहरूलाई भंग गर्न र सम्पूर्ण अस्तित्वको अन्तर्निहित एकतालाई प्रकट गर्न चाहन्छौं।",
    brahmanQuote: "\"ब्रह्म सत्य हो, संसार एक प्रकटता हो, र व्यक्तिगत आत्मा ब्रह्मसँग भिन्न छैन।\"",
