    eternalEchoOfNonDuality: "ଅଦ୍ୱୈତର ଶାଶ୍ୱତ ପ୍ରତିଧ୍ୱନି",
    welcomeDescription: "ଆଚାର୍ଯ୍ୟ ଶଙ୍କର ସଂସ୍କୃତିକ ଏକତା ନ୍ୟାସ ଦ୍ୱାରା ପବିତ୍ର ଡିଜିଟାଲ ପୋର୍ଟାଲ, ଅଦ୍ୱୈତ ବେଦାନ୍ତର ସଂରକ୍ଷଣ, ଡିଜିଟାଲାଇଜେସନ୍ ଏବଂ ବିଶ୍ୱବ୍ୟାପୀ ପ୍ରସାରଣକୁ ଉଦ୍ଦିଶ୍ୟ କରିଛି। ଆଦି ଶଙ୍କରାଚାର୍ଯ୍ୟଙ୍କ ଉତ୍ତରାଧିକାରରୁ ପ୍ରେରିତ, ଜୀବ-ବ୍ରହ୍ମ-ଏକ୍ୟର ଗଭୀର ସତ୍ୟକୁ ଅନୁସନ୍ଧାନ କରୁଛି: ବ୍ୟକ୍ତିଗତ ଆତ୍ମା ଏବଂ ସର୍ବୋଚ୍ଚ ସତ୍ୟର ମୂଳ ଏକତ୍ୱ।",
    treasuryOfWisdom: "ଜ୍ଞାନର ଧନ",
    treasuryIntro: "ନ୍ୟାସ ନିକଟରେ ଏକ ବିଶାଳ ସଂଗ୍ରହ ସଂଗ୍ରହ କରାଯାଇଛି, ଯାହା ପ୍ରାରମ୍ଭିକ \"ତ୍ରିପୁଟୀ କାନନ\" (ପ୍ରସ୍ଥାନତ୍ରୟୀ) ଠାରୁ ଆରମ୍ଭ କରି ଅନ୍ତିମ ଅଦ୍ୱୈତ ଆଚାର୍ଯ୍ୟମାନଙ୍କ ଜଟିଳ ତର୍କଶାସ୍ତ୍ରୀୟ କାର୍ଯ୍ୟ ପର୍ଯ୍ୟନ୍ତ ବିସ୍ତାରିତ। ଆମର ଅର୍କାଇଭ୍ ଗୁଡ଼ିକ ଅନ୍ତର୍ଭୁକ୍ତ କରେ:",
    prasthanatriyaBhashyasLabel: "ପ୍ରସ୍ଥାନତ୍ରୟୀ ଭାଷ୍ୟ:",
    prasthanatriyaBhashyasDesc: "ଉପନିଷଦ, ଭଗବଦ୍ ଗୀତା, ଏବଂ ବ୍ରହ୍ମ ସୂତ୍ରର ପ୍ରାରମ୍ଭିକ ଭାଷ୍ୟଗୁଡ଼ିକ।",
    prakaranaGranthasLabel: "ପ୍ରକରଣ ଗ୍ରନ୍ଥ:",
    prakaranaGranthasDesc: "ବିବେକଚୂଡାମଣି, ଉପଦେଶ ସହସ୍ରୀ, ଏବଂ ଆତ୍ମ ବୋଧ ଭଳି ଆବଶ୍ୟକ ପ୍ରାରମ୍ଭିକ ମୋନୋଗ୍ରାଫଗୁଡ଼ିକ।",
    scholasticTraditionLabel: "ଶାସ୍ତ୍ରୀୟ ପରମ୍ପରା:",
    scholasticTraditionDesc: "ଭାମତୀ ଏବଂ ବିବରଣା ପରମ୍ପରାର ଗଭୀର ଅଧ୍ୟୟନ, ପଦ୍ମପାଦ, ବାଚସ୍ପତି ମିଶ୍ର, ଏବଂ ଵିଦ୍ୟାରଣ୍ୟ ସ୍ୱାମୀଙ୍କ ଭଳି ଆଚାର୍ଯ୍ୟମାନଙ୍କ କାର୍ଯ୍ୟଗୁଡ଼ିକ ସମେତ।",
    regionalLuminariesLabel: "ଅଞ୍ଚଳୀୟ ପ୍ରତିଭାଗୁଡ଼ିକ:",
    regionalLuminariesDesc: "ଭାରତର ବିଭିନ୍ନ ସ୍ଥାନରୁ ଦୁର୍ଲଭ ଏବଂ ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ କାର୍ଯ୍ୟଗୁଡ଼ିକ, ଯେପରିକି ଶ୍ରୀ ବେଲ୍ଲମକୋଣ୍ଡ ରାମ ରାୟ ଏବଂ ଶ୍ରୀମଦ୍ ବୋଧେନ୍ଦ୍ର ସରସ୍ୱତୀଙ୍କ ମହାକୃତିଗୁଡ଼ିକ।",
    ourVisionSanskritikEkta: "ଆମର ଦୃଷ୍ଟିକୋଣ: ସଂସ୍କୃତିକ ଏକତା",
    visionDescription: "ଆଚାର୍ଯ୍ୟ ଶଙ୍କର ସଂସ୍କୃତିକ ଏକତା ନ୍ୟାସର ମିଶନ୍ ସହିତ ସମନ୍ୱୟରେ, ଏହି ଲାଇବ୍ରେରୀ କେବଳ ପୁସ୍ତକର ଏକ ସଂଗ୍ରହ ନୁହେଁ; ଏହା ସାର୍ବଜନୀନ ସମନ୍ୱୟ ପାଇଁ ଏକ ଉପକରଣ। ଅଦ୍ୱୈତ ଦର୍ଶନକୁ ସମସ୍ତଙ୍କ ପାଇଁ ଉପଲବ୍ଧ କରାଇ ଆମେ \"ଅନ୍ୟତ୍ୱ\"ର ସୀମାକୁ ଦୂର କରିବାକୁ ଏବଂ ସମସ୍ତ ଅସ୍ତିତ୍ୱର ମୂଳ ଏକତ୍ୱକୁ ପ୍ରକାଶ କରିବାକୁ ଚାହୁଁଛୁ।",
    brahmanQuote: "\"ବ୍ରହ୍ମ ହେଉଛି ଏକମାତ୍ର ସତ୍ୟ, ଜଗତ ଏକ ଦେଖାଯାଉଥିବା ଜିନିଷ, ଏବଂ ବ୍ୟକ୍ତିଗତ ଆତ୍ମା ବ୍ରହ୍ମରୁ ଅଲଗା ନୁହେଁ।\"",
    featuresOfDigitalLibrary: "ଡିଜିଟାଲ ଲାଇବ୍ରେରୀର ବିଶେଷତା",
    authenticTranscriptionsLabel: "ଅସଲି ଟ୍ରାନ୍ସକ୍ରିପ୍ସନ୍:",
    authenticTranscriptionsDesc: "ଆଧୁନିକ ପାଠକମାନଙ୍କ ପାଇଁ ସଠିକ ଫର୍ମାଟିଂ ସହିତ ସଠିକ ଭାବରେ ଡିଜିଟାଇଜ୍ କରାଯାଇଥିବା ସଂସ୍କୃତ ପାଠ୍ୟଗୁଡ଼ିକ।",
    manuscriptPreservationLabel: "ପାଣ୍ଡୁଲିପି ସଂରକ୍ଷଣ:",
    manuscriptPreservationDesc: "ଆମର ଐତିହ୍ୟର ଦୀର୍ଘାୟୁ ନିଶ୍ଚିତ କରିବା ପାଇଁ ଦୁର୍ଲଭ ସଂସ୍କରଣର ଉଚ୍ଚ-ରେଜୋଲୁସନ୍ ସ୍କାନ୍।",
    scholarlySearchLabel: "ଶାସ୍ତ୍ରୀୟ ସନ୍ଧାନ:",
    scholarlySearchDesc: "ଲେଖକ, କାଳ, କିମ୍ବା ନିର୍ଦ୍ଦିଷ୍ଟ ଦାର୍ଶନିକ ଉପବିଷୟ ଦ୍ୱାରା ନାଭିଗେଟ୍ କରନ୍ତୁ।",
    saVidyaQuote: "\"ଜ୍ଞାନ ହେଉଛି ସେଇ ଯାହା ମୁକ୍ତି ଦେଇଥାଏ।\" — ସା ଵିଦ୍ୟା ଯା ଵିମୁକ୍ତୟେ",
    invitationText: "ଆମେ ଆପଣଙ୍କୁ ଏହି ଜ୍ଞାନର ସାଗରକୁ ଅନୁସନ୍ଧାନ କରିବାକୁ ଆମନ୍ତ୍ରଣ କରୁଛୁ। ଆଚାର୍ଯ୍ୟ ଶଙ୍କରଙ୍କ କୃପା ଆପଣଙ୍କ ଅନୁସନ୍ଧାନକୁ ଅସ୍ଥାୟୀରୁ ଶାଶ୍ୱତ ପର୍ଯ୍ୟନ୍ତ ନେଇଯାଉ।",
    managedByNyas: "ଆଚାର୍ଯ୍ୟ ଶଙ୍କର ସଂସ୍କୃତିକ ଏକତା ନ୍ୟାସ, ମଧ୍ୟ ପ୍ରଦେଶ ଦ୍ୱାରା ପରିଚାଳିତ।",
