    eternalEchoOfNonDuality: "Η αιώνια ηχώ της μη-δυαδικότητας",
    welcomeDescription: "Μια ιερή ψηφιακή πύλη του Acharya Shankar Sanskritik Ekta Nyas, αφιερωμένη στη διατήρηση, ψηφιοποίηση και παγκόσμια διάδοση της Advaita Vedanta. Εμπνευσμένη από την κληρονομιά του Adi Shankaracharya, εξερευνώντας τη βαθιά αλήθεια της Jiva-Brahma-Aikya: την ουσιαστική ενότητα της ατομικής ψυχής και της Υπέρτατης Πραγματικότητας.",
    treasuryOfWisdom: "Το θησαυροφυλάκιο της σοφίας",
    treasuryIntro: "Ο Nyas έχει επιμεληθεί σχολαστικά μια εκτενή συλλογή κειμένων, από τον θεμελιώδη \"Τριπλό Κανόνα\" (Prasthanatrayi) ως τα εκλεπτυσμένα διαλεκτικά έργα των μετέπειτα δασκάλων της Advaita. Τα αρχεία μας περιλαμβάνουν:",
