    scholasticTraditionLabel: "Η σχολαστική παράδοση:",
    scholasticTraditionDesc: "Βαθιές μελέτες στις σχολές Bhamati και Vivarana, συμπεριλαμβανομένων των έργων δασκάλων όπως ο Padmapada, ο Vachaspati Misra και ο Vidyaranya Swami.",
    regionalLuminariesLabel: "Περιφερειακοί φωστήρες:",
    regionalLuminariesDesc: "Σπάνια και σημαντικά έργα από όλη την Ινδία, όπως τα αριστουργήματα του Sri Bellamkonda Rama Raya και του Shrimad Bodhendra Saraswati.",
    ourVisionSanskritikEkta: "Το όραμά μας: Sanskritik Ekta",
    visionDescription: "Σε ευθυγράμμιση με την αποστολή του Acharya Shankar Sanskritik Ekta Nyas, αυτή η βιβλιοθήκη είναι κάτι περισσότερο από ένα αποθετήριο βιβλίων· είναι ένα εργαλείο για οικουμενική αρμονία. Κάνοντας τη φιλοσοφία Advaita προσβάσιμη σε όλους, στοχεύουμε να διαλύσουμε τα σύνορα της \"ετερότητας\" και να αποκαλύψουμε την υποκείμενη ενότητα όλης της ύπαρξης.",
    brahmanQuote: "\"Το Brahman είναι η μόνη Αλήθεια, ο Κόσμος είναι φαινόμενο, και ο Ατομικός Εαυτός δεν είναι τίποτα άλλο παρά Brahman.\"",
